// Evalua la salida de Transformacion/ejecutar_proceso.py y resume el resultado.
// Falla la ejecucion si el codigo de salida no es 0, si falta la revision o si la verificacion no es OK.
const EXIGIR_INGESTA = true;
const resultados = [];
for (const item of $input.all()) {
  const stdout = String(item.json.stdout || '');
  const lineas = stdout.split(/\r?\n/);
  const coincidencia = stdout.match(/CODIGO_SALIDA=(\d+)\s*$/);
  const codigo = coincidencia ? Number(coincidencia[1]) : null;
  const buscar = (prefijo) => lineas.find((l) => l.startsWith(prefijo)) || '';
  const valor = (prefijo) => buscar(prefijo).replace(prefijo, '').trim();
  const modo = buscar('=== MODO');
  const ingesta = valor('Ingesta correcta:');
  const verificacion = buscar('Verificacion:');
  const reparto = valor('Reparto:');
  const revision = valor('Revision generada:');
  const carpeta = valor('Carpeta de salida:');
  const archivos = lineas
    .filter((l) => l.startsWith('Archivo para '))
    .map((l) => {
      const m = l.match(/^Archivo para (.+?): (.+?) \((\d+) filas\)$/);
      return m ? { asesor: m[1], archivo: m[2].split('/').pop(), ruta: m[2], filas: Number(m[3]) } : { detalle: l };
    });
  const csv = lineas.filter((l) => l.trim().startsWith('- Ingesta/output/')).map((l) => l.trim().slice(2));
  const posIngesta = ingesta ? stdout.indexOf('Ingesta correcta:') : -1;
  const posRevision = revision ? stdout.indexOf('Revision generada:') : -1;

  const problemas = [];
  if (codigo !== 0) problemas.push(`el proceso termino con codigo ${codigo}`);
  if (EXIGIR_INGESTA && !ingesta) problemas.push('no se confirmo una ingesta correcta');
  if (EXIGIR_INGESTA && ingesta && revision && posIngesta > posRevision) problemas.push('los archivos aparecen antes que la ingesta');
  if (!revision) problemas.push('no se genero el archivo de revision');
  if (!verificacion.startsWith('Verificacion: OK')) problemas.push('la verificacion no es OK');
  if (problemas.length) {
    const detalle = lineas.filter((l) => /ERROR|FALLO|faltan valores|Verificacion|marcada para revision|maestro/.test(l)).join('\n');
    throw new Error(`No hay archivos validos de esta ejecucion: ${problemas.join('; ')}.\n` + (detalle || stdout.slice(-2000)));
  }
  resultados.push({
    json: {
      modo,
      ingesta_csv_nuevo: ingesta || '(no aplica: demostracion con CSV existentes)',
      reparto,
      archivos_por_asesor: archivos,
      revision,
      carpeta_salida: carpeta,
      verificacion,
      csv_consolidados: csv,
      codigo_salida: codigo,
    },
  });
}
return resultados;
